"""Private CI fixture materials generated by the pinned Tor authority tool."""

import base64
import binascii
from datetime import datetime
import math
import os
from pathlib import Path
import re
import secrets
import stat
import subprocess
import tempfile
import time


class MaterialsError(RuntimeError):
    pass


class DeadlineExceeded(MaterialsError):
    pass


class Cancelled(MaterialsError):
    pass


class CleanupError(MaterialsError):
    pass


cancelled = False

CERTIFICATE = re.compile(
    r"\Adir-key-certificate-version 3\n"
    r"fingerprint (?P<fingerprint>[0-9A-F]{40})\n"
    r"dir-key-published (?P<published>\d{4}-\d\d-\d\d \d\d:\d\d:\d\d)\n"
    r"dir-key-expires (?P<expires>\d{4}-\d\d-\d\d \d\d:\d\d:\d\d)\n"
    r"dir-identity-key\n"
    r"-----BEGIN RSA PUBLIC KEY-----\n"
    r"(?P<identity>(?:[A-Za-z0-9+/=]+\n)+)"
    r"-----END RSA PUBLIC KEY-----\n"
    r"dir-signing-key\n"
    r"-----BEGIN RSA PUBLIC KEY-----\n"
    r"(?P<signing>(?:[A-Za-z0-9+/=]+\n)+)"
    r"-----END RSA PUBLIC KEY-----\n"
    r"dir-key-crosscert\n"
    r"-----BEGIN ID SIGNATURE-----\n"
    r"(?P<crosscert>(?:[A-Za-z0-9+/=]+\n)+)"
    r"-----END ID SIGNATURE-----\n"
    r"dir-key-certification\n"
    r"-----BEGIN SIGNATURE-----\n"
    r"(?P<certification>(?:[A-Za-z0-9+/=]+\n)+)"
    r"-----END SIGNATURE-----\n\Z"
)


def certificate_metadata(data):
    try:
        match = CERTIFICATE.fullmatch(data.decode("ascii"))
        if match is None:
            raise ValueError()
        for name in ("identity", "signing", "crosscert", "certification"):
            encoded = match[name].replace("\n", "").encode("ascii")
            decoded = base64.b64decode(encoded, validate=True)
            if not decoded or base64.b64encode(decoded) != encoded:
                raise ValueError()
        published = datetime.strptime(match["published"], "%Y-%m-%d %H:%M:%S")
        expires = datetime.strptime(match["expires"], "%Y-%m-%d %H:%M:%S")
        if expires <= published:
            raise ValueError()
    except (UnicodeError, ValueError, binascii.Error):
        raise MaterialsError("certificate-format") from None
    return {
        "v3_identity_fingerprint": match["fingerprint"],
        "published": match["published"],
        "expires": match["expires"],
    }


class AuthorityMaterials:
    def __init__(self, binary, deadline):
        if (
            os.environ.get("GITHUB_ACTIONS") != "true"
            or os.environ.get("TOR_REAL_ISOLATED") != "yes"
        ):
            raise MaterialsError("isolated-ci-required")
        if not os.path.isabs(binary):
            raise MaterialsError("absolute-tool-required")
        if not math.isfinite(deadline):
            raise MaterialsError("invalid-deadline")
        self.binary = binary
        self.deadline = deadline
        self.process = None
        self._temp = None
        self._input = None
        self._closed = False
        self.metadata = None

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, traceback):
        self.close()
        return False

    def _remaining(self):
        if cancelled:
            raise Cancelled("cancelled")
        remaining = self.deadline - time.monotonic()
        if remaining <= 0:
            raise DeadlineExceeded("deadline")
        return remaining

    def _check_file(self, name):
        path = Path(self._temp.name) / name
        info = path.lstat()
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_uid != os.geteuid()
            or stat.S_IMODE(info.st_mode) & 0o177
            or not 0 < info.st_size <= 16384
        ):
            raise MaterialsError("output-file")
        return path

    def _validate(self):
        root = Path(self._temp.name)
        info = root.lstat()
        if (
            not stat.S_ISDIR(info.st_mode)
            or info.st_uid != os.geteuid()
            or stat.S_IMODE(info.st_mode) != 0o700
        ):
            raise MaterialsError("private-directory")
        for name, label in (
            ("authority_identity_key", "ENCRYPTED PRIVATE KEY"),
            ("authority_signing_key", "RSA PRIVATE KEY"),
        ):
            data = self._check_file(name).read_bytes()
            begin = ("-----BEGIN " + label + "-----\n").encode("ascii")
            end = ("-----END " + label + "-----\n").encode("ascii")
            if not data.startswith(begin) or not data.endswith(end):
                raise MaterialsError("private-key-format")
            encoded = data[len(begin):-len(end)].replace(b"\n", b"")
            try:
                decoded = base64.b64decode(encoded, validate=True)
                if not decoded or base64.b64encode(decoded) != encoded:
                    raise ValueError()
            except (ValueError, binascii.Error):
                raise MaterialsError("private-key-format") from None
        certificate = self._check_file("authority_certificate").read_bytes()
        self.metadata = certificate_metadata(certificate)

    def generate(self):
        if self._closed or self._temp is not None:
            raise MaterialsError("single-use")
        self._remaining()
        try:
            self._temp = tempfile.TemporaryDirectory(
                prefix="tor-authority-", dir="/tmp"
            )
            self._input = tempfile.TemporaryFile(
                mode="w+b", dir=self._temp.name
            )
            self._input.write(secrets.token_hex(32).encode("ascii") + b"\n")
            self._input.seek(0)
            self._remaining()
            self.process = subprocess.Popen(
                [
                    self.binary,
                    "--create-identity-key",
                    "--passphrase-fd", "0",
                    "-i", "authority_identity_key",
                    "-s", "authority_signing_key",
                    "-c", "authority_certificate",
                    "-m", "1",
                ],
                cwd=self._temp.name,
                stdin=self._input,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                close_fds=True,
            )
            while True:
                budget = min(0.05, self._remaining())
                try:
                    status = self.process.wait(timeout=budget)
                except subprocess.TimeoutExpired:
                    continue
                self._remaining()
                if status != 0:
                    raise MaterialsError("tool-exit")
                break
            self._validate()
            self._remaining()
            return self
        except BaseException:
            self.close()
            raise

    def close(self):
        if self._closed:
            return
        cleanup_deadline = min(
            self.deadline + 5.0, time.monotonic() + 5.0
        )
        try:
            if self.process is not None:
                if self.process.poll() is None:
                    try:
                        self.process.terminate()
                    except ProcessLookupError:
                        pass
                    try:
                        self.process.wait(
                            timeout=min(
                                2.0,
                                max(0.0, cleanup_deadline - time.monotonic()),
                            )
                        )
                    except subprocess.TimeoutExpired:
                        try:
                            self.process.kill()
                        except ProcessLookupError:
                            pass
                        self.process.wait(
                            timeout=max(
                                0.0, cleanup_deadline - time.monotonic()
                            )
                        )
                self.process.wait(timeout=0)
                if self.process.returncode is None:
                    raise CleanupError("child-unreaped")
        except (OSError, subprocess.TimeoutExpired):
            raise CleanupError("child-unreaped") from None
        try:
            if self._input is not None:
                self._input.close()
            if self._temp is not None:
                self._temp.cleanup()
        except OSError:
            raise CleanupError("resource-cleanup") from None
        self.metadata = None
        self._closed = True
